{
  "items": [
    {
      "name": "Polynomial.wronskian",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : CommRing R] → Polynomial R → Polynomial R → Polynomial R"
    },
    {
      "name": "Polynomial.wronskian_add_right",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a b c : Polynomial R), a.wronskian (b + c) = a.wronskian b + a.wronskian c"
    },
    {
      "name": "Polynomial.wronskianBilin",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "definition",
      "type": "(R : Type u_1) → [inst : CommRing R] → Polynomial R →ₗ[R] Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "Polynomial.wronskian_add_left",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a b c : Polynomial R), (a + b).wronskian c = a.wronskian c + b.wronskian c"
    },
    {
      "name": "Polynomial.wronskian_neg_right",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a b : Polynomial R), a.wronskian (-b) = -a.wronskian b"
    },
    {
      "name": "IsCoprime.wronskian_eq_zero_iff",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [NoZeroDivisors R] {a b : Polynomial R},\n  IsCoprime a b → (a.wronskian b = 0 ↔ Polynomial.derivative a = 0 ∧ Polynomial.derivative b = 0)"
    },
    {
      "name": "Polynomial.wronskian_neg_left",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a b : Polynomial R), (-a).wronskian b = -a.wronskian b"
    },
    {
      "name": "Polynomial.wronskian_neg_eq",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a b : Polynomial R), -a.wronskian b = b.wronskian a"
    }
  ]
}
